import { useEffect } from "react";

const PAGE_STYLESHEET_ID = "active-page-stylesheet";

export default function usePageStyles(href) {
  useEffect(() => {
    const link = document.createElement("link");
    link.id = PAGE_STYLESHEET_ID;
    link.rel = "stylesheet";
    link.href = href;
    document.head.appendChild(link);

    return () => {
      link.remove();
    };
  }, [href]);
}
